  <canvas id="pendulum-canvas" width="500" height="500"></canvas>
  <script>
    // Get the canvas element
    const canvas = document.getElementById("pendulum-canvas");
    const ctx = canvas.getContext("2d");

    // Set the initial angle and speed
    let initialAngle = 0;
    let speed = 0.1;

    // Set the gravity constant
    const g = 0.1;

    // Set the pendulum's length
    const pendulumLength = 100;

    // Set the canvas dimensions
    const canvasWidth = canvas.width;
    const canvasHeight = canvas.height;

    // Draw the pendulum
    function drawPendulum() {
      ctx.clearRect(0, 0, canvasWidth, canvasHeight);
      ctx.beginPath();
      ctx.arc(
        canvasWidth / 2,
        canvasHeight / 2,
        pendulumLength * Math.sin(initialAngle),
        0,
        2 * Math.PI
      );
      ctx.lineWidth = 2;
      ctx.strokeStyle = "black";
      ctx.stroke();
    }

    // Update the pendulum's position
    function updatePendulum() {
      initialAngle += speed;
      speed += g * initialAngle;
    }

    // Main animation loop
    function animate() {
      requestAnimationFrame(animate);
      updatePendulum();
      drawPendulum();
    }

    // Add event listener to the release button
    document.getElementById("release-button").addEventListener("click", () => {
      initialAngle = parseInt(document.getElementById("initial-angle").value);
      animate();
    });

    // Draw the pendulum for the first time
